/**
 * Derive typed application data + regression baselines from the preserved
 * legacy definitions. Run with `npm run sync:legacy`.
 *
 * The generated files are committed on purpose: reviewers can see exactly
 * which algorithm sources the application ships, and `legacy-frames.json`
 * is a fixed oracle captured from the pre-refactor implementation.
 */
import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { ex, problems, I, langExamples, groups } from '../legacy/algorithm-definitions.js';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '..');
const HEADER = '// AUTO-GENERATED by scripts/sync-legacy-data.mjs from legacy/algorithm-definitions.js\n// DO NOT EDIT BY HAND. Run `npm run sync:legacy` to refresh.\n';

function emit(relPath, body, withHeader = true) {
  const target = resolve(root, relPath);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, (withHeader ? HEADER : '') + body, 'utf8');
  console.log('  wrote', relPath);
}
const json = (value) => JSON.stringify(value, null, 2);

emit('src/domain/algorithms/catalog.generated.ts', `
import type { AlgorithmCatalog, AlgorithmGroup } from './types';

export const ALGORITHM_CATALOG: AlgorithmCatalog = ${json(ex)};

export const ALGORITHM_GROUPS: Array<[AlgorithmGroup, string]> = ${json(groups)};
`);

emit('src/domain/algorithms/languageExamples.generated.ts', `
import type { CodeLanguage } from './types';

export const LANGUAGE_EXAMPLES: Partial<Record<CodeLanguage, Record<string, string>>> = ${json(langExamples)};
`);

emit('src/domain/problems/catalog.generated.ts', `
import type { PracticeProblem } from './types';

export const PROBLEM_CATALOG: PracticeProblem[] = ${json(problems)};
`);

emit('src/i18n/messages.generated.ts', `
import type { MessageDictionary } from './types';

/** Legacy UI copy, verbatim from the v0.1 single-file prototype. */
export const LEGACY_MESSAGES: MessageDictionary = ${json(I)};
`);

// Capture the exact frame stream produced by the legacy JS worker semantics:
// structured-clone the state, truncate the message, cap at 500 frames.
function captureFrames(entry) {
  const frames = [];
  const trace = (state, message = '') => {
    if (frames.length >= 500) throw new Error('Too many trace steps (limit: 500)');
    const snap = JSON.parse(JSON.stringify(state));
    frames.push({ state: snap, message: String(message).slice(0, 240) });
  };
  new Function('input', 'trace', '"use strict";\n' + entry.code)(entry.input, trace);
  return frames;
}

const baseline = {};
for (const [id, entry] of Object.entries(ex)) {
  baseline[id] = captureFrames(entry);
}
emit('src/test/fixtures/legacy-frames.json', json(baseline) + '\n', false);

console.log('\nBaseline captured from', Object.keys(ex).length, 'algorithms:');
for (const [id, frames] of Object.entries(baseline)) {
  console.log(`  ${id.padEnd(12)} ${String(frames.length).padStart(3)} frames`);
}
